-- GameHub seed data
-- Contains active game records exported from Supabase.
-- This file inserts reference platforms and 97 active games.
-- No game_platforms rows are added because no verified mappings were provided.
--
-- IMPORTANT:
-- ON CONFLICT (id) DO UPDATE overwrites matching game records.
-- Test on a separate/empty database before running against your main database.

BEGIN;

INSERT INTO public.platforms (name)
VALUES
    ('PC'),
    ('PlayStation'),
    ('Xbox'),
    ('Nintendo')
ON CONFLICT (name) DO NOTHING;

INSERT INTO public.games (
    id,
    name,
    genre,
    year,
    image,
    description,
    igdb_id,
    is_deleted
)
VALUES
    (1, 'Elden Ring', 'Action RPG', 2022, 'https://cdn.cloudflare.steamstatic.com/steam/apps/1245620/header.jpg', 'An action role-playing game developed by FromSoftware.', 119133, FALSE),
    (2, 'Cyberpunk 2077', 'Action RPG', 2020, 'https://cdn.cloudflare.steamstatic.com/steam/apps/1091500/header.jpg', 'An open-world role-playing game set in Night City.', 1877, FALSE),
    (3, 'Hogwarts Legacy', 'Action RPG', 2023, 'https://cdn.cloudflare.steamstatic.com/steam/apps/990080/header.jpg', 'An open-world action RPG set in the Wizarding World.', NULL, FALSE),
    (4, 'Red Dead Redemption 2', 'Action Adventure', 2019, 'https://cdn.cloudflare.steamstatic.com/steam/apps/1174180/header.jpg', 'An open-world western action-adventure game.', 25076, FALSE),
    (5, 'Grand Theft Auto V', 'Action Adventure', 2015, 'https://cdn.cloudflare.steamstatic.com/steam/apps/271590/header.jpg', 'An open-world action-adventure game set in Los Santos.', 1020, FALSE),
    (9, 'Hollow Knight', 'Metroidvania, Action Adventure', 2017, 'https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/367520/header.jpg', 'Hollow Knight is a 2D action-adventure game set in the mysterious underground kingdom of Hallownest. Explore a vast interconnected world, battle challenging enemies, discover hidden secrets, and unlock new abilities.', 14593, FALSE),
    (10, 'Hollow Knight: Silksong', 'Action Adventure', 2025, 'https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/1030300/header.jpg', 'Hollow Knight: Silksong is an action-adventure game where players explore a mysterious kingdom, battle dangerous enemies, discover secrets, and overcome challenging bosses as Hornet.', NULL, FALSE),
    (11, 'The Witcher 3: Wild Hunt', 'Role-playing (RPG)', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaarl.jpg', 'The Witcher 3: Wild Hunt is an open-world action role-playing game developed by CD Projekt Red.

Set in a dark fantasy world, the game follows Geralt of Rivia, a monster hunter searching for his adopted daughter, Ciri, while navigating political conflicts and supernatural threats. Gameplay features exploration, combat, character progression, and branching narratives shaped by player choices. Widely acclaimed for its writing, world-building, and depth, it is considered one of the most influential RPGs of its generation.', 1942, FALSE),
    (12, 'Portal 2', 'Platform', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rs4.jpg', 'Sequel to the acclaimed Portal (2007), Portal 2 pits the protagonist of the original game, Chell, and her new robot friend, Wheatley, against more puzzles conceived by GLaDOS, an A.I. with the sole purpose of testing the Portal Gun''s mechanics and taking revenge on Chell for the events of Portal. As a result of several interactions and revelations, Chell once again pushes to escape Aperture Science Labs.', 72, FALSE),
    (13, 'The Elder Scrolls V: Skyrim', 'Role-playing (RPG)', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocs1l.jpg', 'Skyrim reimagines and revolutionizes the open-world fantasy epic, bringing to life a complete virtual world open for you to explore any way you choose. Play any type of character you can imagine, and do whatever you want; the legendary freedom of choice, storytelling, and adventure of The Elder Scrolls is realized like never before.', 472, FALSE),
    (14, 'Grand Theft Auto: San Andreas', 'Shooter', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lb9.jpg', 'Returning after his mother''s murder to the semi-fictional city of Los Santos (based on Los Angeles), Carl Johnson, a former gang banger, must take back the streets for his family and friends by gaining respect and once again gaining control over the streets. However, a story filled with crime, lies and corruption will lead him to trudge the entire state of San Andreas (based on California and Nevada) to rebuild his life.', 732, FALSE),
    (15, 'Portal', 'Platform', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coay61.jpg', 'Waking up in a seemingly empty laboratory, the player is made to complete various physics-based puzzle challenges through numerous test chambers in order to test out the new Aperture Science Handheld Portal Device, without an explanation as to how, why or by whom.', 71, FALSE),
    (16, 'God of War', 'Role-playing (RPG)', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobkt6.jpg', 'God of War is the sequel to God of War III as well as a continuation of the canon God of War chronology. Unlike previous installments, this game focuses on Norse mythology and follows an older and more seasoned Kratos and his son Atreus in the years since the third game. It is in this harsh, unforgiving world that he must fight to survive… and teach his son to do the same.', 19560, FALSE),
    (17, 'The Last of Us', 'Shooter', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r7f.jpg', 'The Last of Us is a third-person action-adventure game featuring a mix of exploration, stealth and combat. Players face both infected creatures and hostile human enemies while progressing through varied environments. The game includes a narrative-driven single-player campaign and a competitive online multiplayer mode called Factions. Trophy support is included, and additional downloadable content was made available separately.', 1009, FALSE),
    (18, 'Half-Life 2', 'Shooter', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1nmw.jpg', '1998. HALF-LIFE sends a shock through the game industry with its combination of pounding action and continuous, immersive storytelling.

NOW. By taking the suspense, challenge and visceral charge of the original, and adding startling new realism and responsiveness, Half-Life 2 opens the door to a world where the player''s presence affects everything around them, from the physical environment to the behaviors even the emotions of both friends and enemies.', 233, FALSE),
    (19, 'BioShock', 'Shooter', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mli.jpg', 'BioShock is a horror-themed first-person shooter set in a steampunk underwater dystopia. The player is urged to turn everything into a weapon: biologically modifying their own body with Plasmids, hacking devices and systems, upgrading their weapons, crafting new ammo variants, and experimenting with different battle techniques are all possible. The game is described by the developers as a spiritual successor to their previous PC title System Shock 2. BioShock received high praise in critical reviews for its atmospheric audio and visual quality, absorbing and original plot and its unique gaming experience.', 20, FALSE),
    (20, 'Assassin''s Creed II', 'Platform', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rcf.jpg', 'Discover an intriguing and epic story of power, revenge and conspiracy set during a pivotal moment in history: the Italian Renaissance.
Experience the freedom and immersion of an all new open world and mission structure with settings such as the rooftops and canals of beautiful Venice. Your options in combat, assassination and escape are vast, with many new weapons, settings and gameplay elements.', 127, FALSE),
    (21, 'Grand Theft Auto: Vice City', 'Shooter', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lbb.jpg', 'In the year 1986, Tommy Vercetti is heavily indebted to his mafia superiors after a drug deal gone awry, but his dreams of taking over Vice City (based on Miami) push him down a different path. Featuring a wide variety of vehicles and weapons, radio stations playing hit songs from the era and an intense atmosphere, GTA: Vice City is an open-world sandbox satire of ''80''s Miami.', 733, FALSE),
    (22, 'The Legend of Zelda: Breath of the Wild', 'Puzzle', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3p2d.jpg', 'The Legend of Zelda: Breath of the Wild is the first 3D open-world game in the Zelda series. Link can travel anywhere and be equipped with weapons and armor found throughout the world to grant him various bonuses. Unlike many games in the series, Breath of the Wild does not impose a specific order in which quests or dungeons must be completed. While the game still has environmental obstacles such as weather effects, inhospitable lands, or powerful enemies, many of them can be overcome using the right method. A lot of critics ranked Breath of the Wild as one of the best video games of all time.', 7346, FALSE),
    (23, 'Half-Life', 'Shooter', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc2ea.jpg', 'Half-Life is a 1998 first-person shooter (FPS) game developed by Valve Corporation and published by Sierra Studios for Windows. It was Valve''s debut product and the first game in the Half-Life series. The player assumes the role of Gordon Freeman, a theoretical physicist who must escape from the Black Mesa Research Facility after it is overrun by aliens following a disastrous scientific experiment. Its gameplay consists of diverse combat, exploration and puzzles.', 231, FALSE),
    (24, 'Mass Effect 2', 'Shooter', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20ac.jpg', 'Are you prepared to lose everything to save the galaxy? You''ll need to be, Commander Shephard. It''s time to bring together your greatest allies and recruit the galaxy''s fighting elite to continue the resistance against the invading Reapers. So steel yourself, because this is an astronomical mission where sacrifices must be made. You''ll face tougher choices and new, deadlier enemies. Arm yourself and prepare for an unforgettable intergalactic adventure.

Game Features:

Shift the fight in your favour. Equip yourself with powerful new weapons almost instantly thanks to a new inventory system. Plus, an improved health regeneration system means you''ll spend less time hunting for restorative items.

Make every decision matter. Divisive crew members are just the tip of the iceberg, Commander, because you''ll also be tasked with issues of intergalactic diplomacy. And time''s a wastin'' so don''t be afraid to use new prompt-based actions that let you interrupt conversations, even if they could alter the fate of your crew...and the galaxy.

Forge new alliances, carefully. You''ll fight alongside some of your most trustworthy crew members, but you''ll also get the opportunity to recruit new talent. Just choose your new partners with care because the fate of the galaxy rests on your shoulders, Commander.', 74, FALSE),
    (25, 'Batman: Arkham City', 'Hack and slash/Beat ''em up', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1voh.jpg', 'Batman: Arkham City builds upon the intense, atmospheric foundation of Batman: Arkham Asylum, sending players soaring into Arkham City, the new maximum security "home" for all of Gotham City''s thugs, gangsters and insane criminal masterminds.

Set inside the heavily fortified walls of a sprawling district in the heart of Gotham City, this highly anticipated sequel introduces a brand-new story that draws together a new all-star cast of classic characters and murderous villains from the Batman universe, as well as a vast range of new and enhanced gameplay features to deliver the ultimate experience as the Dark Knight.', 501, FALSE),
    (26, 'BioShock Infinite', 'Shooter', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2n12.jpg', 'BioShock Infinite is the third game in the BioShock series. It is not a direct sequel/prequel to any of the previous BioShock games but takes place in an entirely different setting, although it shares similar features, gameplay and concepts with the previous games. BioShock Infinite features a range of environments that force the player to adapt, with different weapons and strategies for each situation. Interior spaces feature close combat with enemies, but unlike previous games set in Rapture, the setting of Infinite contains open spaces with emphasis on sniping and ranged combat against as many as fifteen enemies at once.', 538, FALSE),
    (27, 'Uncharted 4: A Thief''s End', 'Shooter', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r7h.jpg', 'Several years after his last adventure, retired fortune hunter, Nathan Drake, is forced back into the world of thieves. With the stakes much more personal, Drake embarks on a globe-trotting journey in pursuit of a historical conspiracy behind a fabled pirate treasure. His greatest adventure will test his physical limits, his resolve, and ultimately what he''s willing to sacrifice to save the ones he loves.', 7331, FALSE),
    (28, 'Batman: Arkham Asylum', 'Hack and slash/Beat ''em up', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1voj.jpg', 'Batman: Arkham Asylum is an action-adventure game developed by Rocksteady Studios and published by Warner Bros. Interactive Entertainment. Released in 2009, it follows Batman as he battles the Joker, who seizes control of Arkham Asylum and frees its inmates. The game features stealth, combat, and detective elements, with players using Batman''s gadgets and skills to subdue enemies and solve puzzles.

Set in a dark, immersive version of Gotham, the story explores Batman’s psychological battle with his foes, including Harley Quinn, Bane, and Scarecrow. The game received critical acclaim for its gameplay, atmosphere, and storytelling, becoming a defining title in superhero video games.', 500, FALSE),
    (29, 'Red Dead Redemption', 'Shooter', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lcv.jpg', 'A modern-day Western epic, Red Dead Redemption takes John Marston, a relic from the fast-closing time of the gunslinger, through an open world filled with wildlife, mini-games, and shootouts. Marston sets out to hunt down his old gang mates for the government, who have taken away his family. Along his journey, he meets many characters emblematic of the Wild West, heroism, and the new civilization.', 434, FALSE),
    (30, 'Mass Effect', 'Shooter', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1x7o.jpg', 'Mass Effect is an action role-playing game set in the year 2183. The player takes the role of Commander Shepard, a customizable character who serves as Executive Officer aboard the SSV Normandy. After a routine mission goes wrong, Shepard assembles a squad and pursues a threat that escalates into a galaxy-wide conflict. The game features real-time squad-based combat where players choose companions and tactics suited to different enemy types, from biotic-wielding opponents to heavily armored machines.

The game spans a large science fiction universe, with explorable locations ranging from the Citadel space station to alien homeworlds and remote outposts. Player decisions affect mission outcomes, crew relationships, and the overarching narrative across the trilogy.', 73, FALSE),
    (31, 'Horizon Zero Dawn', 'Shooter', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2una.jpg', 'Welcome to a vibrant world rich with the beauty of nature – but inhabited by awe-inspiring, highly advanced machines. As a young machine hunter named Aloy, you must unravel the mysteries of this world and find your own destiny.', 11156, FALSE),
    (32, 'Fallout: New Vegas', 'Shooter', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1u60.jpg', 'In this first-person Western RPG, the player takes on the role of Courier 6, barely surviving after being robbed of their cargo, shot and put into a shallow grave by a New Vegas mob boss. The Courier sets out to track down their robbers and retrieve their cargo, and winds up getting tangled in the complex ideological and socioeconomic web of the many factions and settlements of post-nuclear Nevada.', 16, FALSE),
    (33, 'Tomb Raider', 'Shooter', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rbu.jpg', 'Tomb Raider explores the intense and gritty origin story of Lara Croft and her ascent from a young woman to a hardened survivor. Armed only with raw instincts and the ability to push beyond the limits of human endurance, Lara must fight to unravel the dark history of a forgotten island to escape its relentless hold.', 1164, FALSE),
    (34, 'Far Cry 3', 'Shooter', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vpd.jpg', 'Explore an island playground as stunningly beautiful as it is diverse – from mountain ranges to swampy grasslands and white sandy beaches. Fight your way through the island’s towns, temples, river ports and more.

Encounter a diverse and realistic cast of characters, including one of Far Cry’s most notorious villains: Vaas Montenegro. Dive into this deep and enriching story where morals are questionable and hope is all but abandoned.', 529, FALSE),
    (35, 'Uncharted 2: Among Thieves', 'Shooter', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tnb.jpg', 'In the sequel to Drake''s Fortune, Nathan Drake comes across a map that showcases the location of Marco Polo''s missing ships. It takes him on a journey to find the infamous Cintamani Stone, and uncover the truth behind it.', 565, FALSE),
    (36, 'Marvel''s Spider-Man', 'Hack and slash/Beat ''em up', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r77.jpg', 'Starring the world’s most iconic Super Hero, Spider-Man features the acrobatic abilities, improvisation and web-slinging that the wall-crawler is famous for, while also introducing elements never-before-seen in a Spider-Man game. From traversing with parkour and utilizing the environment, to new combat and blockbuster set pieces, it’s Spider-Man unlike any you’ve played before.', 19565, FALSE),
    (37, 'The Legend of Zelda: Ocarina of Time', 'Puzzle', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3nnx.jpg', 'The Legend of Zelda: Ocarina of Time is the fifth main installment of The Legend of Zelda series and the first to be released for the Nintendo 64. It was one of the most highly anticipated games of its age, and is listed among the greatest video games ever created by numerous websites and magazines. The gameplay of Ocarina of Time was revolutionary for its time, it has arguably made more of an impact on later games in the series than any of its predecessors even though they had the same cores of exploration, dungeons, puzzles and item usage. Among the gameplay mechanics, one of the most noteworthy is the time-traveling system. The game begins with the player controlling the child Link, but later on an adult Link becomes a playable character as well and each of them has certain unique abilities. Ocarina of Time also introduces the use of music to solve puzzles: as new songs are learned, they can be used to solve puzzles, gain access to new areas and warp to different locations. Dungeon exploration is somewhat more puzzle-oriented than in earlier games but they are not too complex.', 1029, FALSE),
    (38, 'Minecraft: Java Edition', 'Simulator', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa77e.jpg', 'Minecraft focuses on allowing the player to explore, interact with, and modify a dynamically generated map made of one-cubic-meter-sized blocks. In addition to blocks, the environment features plants, mobs, and items. Some activities in the game include mining for ore, fighting hostile mobs, and crafting new blocks and tools by gathering various resources found in the game. The game''s open-ended model allows players to create structures, creations, and artwork on various multiplayer servers or their single-player maps. Other features include redstone circuits for logic computations and remote actions, minecarts and tracks, and a mysterious underworld called the Nether. A designated but completely optional goal of the game is to travel to a dimension called the End, and defeat the ender dragon.', 121, FALSE),
    (39, 'Super Mario 64', 'Platform', 1996, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co721v.jpg', 'Mario is super in a whole new way! Combining the finest 3-D graphics ever developed for a video game and an explosive soundtrack, Super Mario 64 becomes a new standard for video games. It''s packed with bruising battles, daunting obstacle courses, and underwater adventures. Retrieve the Power Stars from their hidden locations and confront your arch-nemesis— Bowser, King of the Koopas!

• Run freely in a grassy meadow, tip-toe through a gloomy dungeon, climb to the top of a mountain, or take a swim in the moat!
• Leap headfirst into a watery painting and soon you''ll be searching for the surface in an underwater realm!
• On-the-fly, 3-D rendered gameplay delivers the action of ruthless enemy attacks from every angle!
• Find the Caps that give Mario super powers and ponder the mysteries of the pyramid; you can even race Koopas for fabulous prizes!
• With the Nintendo 64 Controller and its analog
Control Stick, Mario can crawl, kick down obstacles, swim, do reverse flips, and even stick the landing on his backwards somersault!
• Saved game information is stored for up to four players in memory.', 1074, FALSE),
    (40, 'Super Mario World', 'Platform', 1990, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8lo8.jpg', 'A 2D platformer and first entry on the SNES in the Super Mario franchise, Super Mario World follows Mario as he attempts to defeat Bowser''s underlings and rescue Princess Peach from his clutches. The game features a save system, a less linear world map, an expanded movement arsenal and numerous new items for Mario, alongside new approaches to level design and art direction.', 1070, FALSE),
    (41, 'Dark Souls III', 'Role-playing (RPG)', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob9ed.jpg', 'Dark Souls III is an action role-playing game developed by FromSoftware and published by Bandai Namco Entertainment. Released in March 2016, it is the fourth entry in the Souls series and the final instalment in the Dark Souls trilogy. Set in the decaying kingdom of Lothric, players take on the role of the "Ashen One," an undead warrior tasked with rekindling the First Flame to prevent the world from falling into darkness.

The game features challenging combat, intricate level design, and a deep, lore-rich narrative.', 11133, FALSE),
    (42, 'Doom', 'Shooter', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1nc7.jpg', 'Developed by id software, the studio that pioneered the first-person shooter genre and created multiplayer Deathmatch, Doom returns as a brutally fun and challenging modern-day shooter experience. Relentless demons, impossibly destructive guns, and fast, fluid movement provide the foundation for intense, first-person combat – whether you’re obliterating demon hordes through the depths of Hell in the single-player campaign, or competing against your friends in numerous multiplayer modes. Expand your gameplay experience using Doom SnapMap game editor to easily create, play, and share your content with the world.', 7351, FALSE),
    (43, 'Dishonored', 'Puzzle', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coabgu.jpg', 'Dishonored is an immersive first-person action game that casts you as a supernatural assassin driven by revenge. With Dishonored’s flexible combat system, creatively eliminate your targets as you combine the supernatural abilities, weapons and unusual gadgets at your disposal. Pursue your enemies under the cover of darkness or ruthlessly attack them head on with weapons drawn. The outcome of each mission plays out based on the choices you make.', 533, FALSE),
    (44, 'Grand Theft Auto IV', 'Shooter', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lbv.jpg', 'Grand Theft Auto IV is an action-adventure video game developed by Rockstar North and published by Rockstar Games. It is the eleventh title in the Grand Theft Auto series, and the first main entry since 2004''s Grand Theft Auto: San Andreas.

The game is played from a third-person perspective and its world is navigated on-foot or by vehicle. Throughout the single-player mode, players play as Niko Bellic. An online multiplayer mode is included with the game, allowing up to 32 players to engage in both co-operative and competitive gameplay in a recreation of the single-player setting.

Two expansion packs were later released for the game, The Lost and Damned and The Ballad of Gay Tony, which both feature new plots that are interconnected with the main Grand Theft Auto IV storyline, and follow new protagonists.', 731, FALSE),
    (45, 'Undertale', 'Puzzle', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob1t2.jpg', 'A small child falls into the Underground, where monsters have long been banished by humans and are hunting every human that they find. The player controls the child as they try to make it back to the Surface through hostile environments, all the while engaging with a turn-based combat system with puzzle-solving and bullet hell elements, as well as other unconventional game mechanics.', 12517, FALSE),
    (46, 'Bloodborne', 'Role-playing (RPG)', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob99l.jpg', 'An action RPG in which the player embodies a Hunter who, after being transfused with the mysterious blood local to the city of Yharnam, sets off into a "night of the Hunt", an extended night in which Hunters may phase in and out of dream and reality in order to thin the outbreak of abominable beasts that plague the land and, for the more resilient and insightful Hunters, uncover the answers to the Hunt''s many mysteries.', 7334, FALSE),
    (47, 'Super Mario Odyssey', 'Platform', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1mxf.jpg', 'Explore incredible places far from the Mushroom Kingdom as you join Mario and his new ally Cappy on a massive, globe-trotting 3D adventure. Use amazing new abilities, like the power to capture and control objects, animals, and enemies to collect Power Moons so you can power up the Odyssey airship and save Princess Peach from Bowser’s wedding plans!', 26758, FALSE),
    (48, 'Life Is Strange', 'Puzzle', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r8e.jpg', 'Life Is Strange is a five part episodic game that sets out to revolutionize story based choice and consequence games by allowing the player to rewind time and affect the past, present and future.', 7599, FALSE),
    (49, 'Borderlands 2', 'Shooter', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ba3.jpg', 'A new era of shoot and loot is about to begin. Play as one of four new vault hunters facing off against a massive new world of creatures, psychos and the evil mastermind, Handsome Jack. Make new friends, arm them with a bazillion weapons and fight alongside them in 4 player co-op on a relentless quest for revenge and redemption across the undiscovered and unpredictable living planet.', 1011, FALSE),
    (50, 'Mass Effect 3', 'Shooter', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1x7q.jpg', 'Mass Effect 3 is an action role-playing game in which Commander Shepard leads a final campaign against the Reapers, a machine race that has invaded Earth and is conquering civilizations across the galaxy. Players recruit squad members from various species and classes, forge alliances, and make choices that determine which characters survive. Combat features squad-based tactics with combinable biotic and tech powers, blind fire, and enhanced melee attacks.

The game includes a cooperative multiplayer mode where up to four players fight waves of enemies to liberate conflict zones. Progress in multiplayer contributes to war preparedness in the single-player campaign. New and returning squad members join Shepard''s team, including soldier James Vega and EDI, an AI in a physical body.', 75, FALSE),
    (51, 'Call of Duty 4: Modern Warfare', 'Shooter', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wko.jpg', 'Call of Duty 4: Modern Warfare differs from previous installments of the Call of Duty series. Previous Call of Duty games have a distinct three country-specific campaign style, while Call of Duty 4 has a more film-like plot with interlaced story lines from the perspectives of Sgt. Paul Jackson of the Marines 1st Force Recon and Sgt. ''Soap'' MacTavish of the British 22nd SAS Regiment.', 623, FALSE),
    (52, 'Stardew Valley', 'Role-playing (RPG)', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa93h.jpg', 'Stardew Valley is an open-ended country-life RPG! You’ve inherited your grandfather’s old farm plot in Stardew Valley. Armed with hand-me-down tools and a few coins, you set out to begin your new life. Can you learn to live off the land and turn these overgrown fields into a thriving home? It won’t be easy. Ever since Joja Corporation came to town, the old ways of life have all but disappeared. The community center, once the town’s most vibrant hub of activity, now lies in shambles. But the valley seems full of opportunity. With a little dedication, you might just be the one to restore Stardew Valley to greatness!', 17000, FALSE),
    (53, 'The Last of Us Part II', 'Shooter', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ziw.jpg', 'The Last of Us Part II is an action-adventure game set five years after the events of The Last of Us. The player traverses post-apocalyptic environments such as buildings and forests to advance the story. They can use firearms, improvised weapons, and stealth to defend against hostile humans and cannibalistic creatures infected by a mutated strain of the Cordyceps fungus. The game intermittently switches control between Ellie and Abby, and also briefly Joel in the opening sequence. The nimble nature of the player character introduces platforming elements, allowing the player to jump and climb to traverse environments and gain advantages during combat.', 26192, FALSE),
    (54, 'Assassin''s Creed IV Black Flag', 'Adventure', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4qfn.jpg', 'Assassin’s Creed IV Black Flag begins in 1715, when pirates established a lawless republic in the Caribbean and ruled the land and seas. These outlaws paralyzed navies, halted international trade, and plundered vast fortunes. They threatened the power structures that ruled Europe, inspired the imaginations of millions, and left a legacy that still endures.', 1970, FALSE),
    (55, 'Max Payne', 'Shooter', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wb2.jpg', 'Max Payne is a man with nothing to lose in the violent, cold urban night. A fugitive undercover cop framed for murder, hunted by cops and the mob, Max is a man with his back against the wall, fighting a battle he cannot hope to win. Max Payne is a relentless story-driven game about a man on the edge, fighting to clear his name while struggling to uncover the truth about his slain family amongst a myriad of plot-twists and twisted thugs in the gritty bowels of New York during the century''s worst blizzard.

The groundbreaking original cinematic action-shooter, Max Payne introduced the concept of Bullet Time in videogames. Through its stylish slow-motion gunplay combined with a dark and twisted story, Max Payne redefined the action-shooter genre.', 18, FALSE),
    (56, 'Assassin''s Creed', 'Platform', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rrw.jpg', 'Assassin''s Creed is a non-linear action-adventure video game, during which the player controls a 12th-century Levantine Assassin named Altaïr Ibn-La''Ahad during the Third Crusade, whose life is experienced through the Animus by his 21st century descendant, Desmond Miles.', 128, FALSE),
    (57, 'Hades', 'Role-playing (RPG)', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob9kr.jpg', 'A rogue-lite hack and slash dungeon crawler in which Zagreus, son of Hades the Greek god of the dead, attempts to escape his home and his oppressive father by fighting the souls of the dead through the various layers of the ever-shifting underworld, while getting to know and forging relationships with its inhabitants.', 113112, FALSE),
    (58, 'Fallout 3', 'Shooter', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ycw.jpg', 'Fallout 3 from the creators of the award-winning Oblivion, featuring one of the most realized game worlds ever created. Create any kind of character you want and explore the open wastes of post-apocalyptic Washington D.C. Every minute is a fight for survival as you encounter Super Mutants, Ghouls, Raiders and other dangers of the Wasteland. Prepare for the future.

The third game in the Fallout series, Fallout 3 is a singleplayer action role-playing game (RPG) set in a post-apocalyptic Washington DC. Combining the horrific insanity of the Cold War era theory of mutually assured destruction gone terribly wrong, with the kitschy naivety of American 1950s nuclear propaganda, Fallout 3 will satisfy both players familiar with the popular first two games in its series as well as those coming to the franchise for the first time.', 15, FALSE),
    (59, 'Assassin''s Creed Brotherhood', 'Puzzle', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocdky.jpg', 'Assassin''s Creed Brotherhood is an action-adventure game set in Rome, where Master Assassin Ezio Auditore takes on the Templar Order. Players recruit and command a Brotherhood of Assassins to dismantle the corrupt powers entrenched in the city. The game combines stealth, combat, and leadership as Ezio rallies allies to fight alongside him.

The game also introduces a multiplayer mode to the series, where players choose from a roster of unique characters with distinct weapons and assassination techniques, competing against each other online.', 113, FALSE),
    (60, 'Fallout 4', 'Shooter', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yc6.jpg', 'Bethesda Game Studios welcome you to the world of Fallout 4, their most ambitious game ever, and the next generation of open-world gaming. As the sole survivor of Vault 111, you enter a world destroyed by nuclear war. Every second is a fight for survival, and every choice is yours. Only you can rebuild and determine the fate of the Wasteland. Welcome home.', 9630, FALSE),
    (61, 'The Walking Dead', 'Point-and-click', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2j1g.jpg', 'The Walking Dead: Season One (also known as The Walking Dead: The Game) is an episodic interactive drama graphic adventure video game developed and published by Telltale Games. Based on Robert Kirkman''s The Walking Dead comic book series, the game consists of five episodes, released between April and November 2012. It is available for Android, iOS, Kindle Fire HDX, Microsoft Windows, Mac OS X, PlayStation 3, PlayStation Vita, Xbox 360, PlayStation 4 and Xbox One. The game is the first of The Walking Dead video game series published by Telltale.', 1871, FALSE),
    (62, 'Dragon Age: Origins', 'Role-playing (RPG)', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mvs.jpg', 'Dragon Age: Origins is a third-person role-playing game described as a spiritual successor to Baldur''s Gate and Neverwinter Nights franchises. Players create their own character by customizing gender and appearance as well as choosing a race and class. Combat is in real time with the ability to pause at any moment: tactical options include an editor which allows the player to give the AI detailed instructions on how to behave in every possible situation. Although the main storyline is the same for every character created, the game features six unique prologues, two for each race. Dragon Age: Origins received critical acclaim upon release, with praise mostly directed at its story, setting, characters, music and combat system.', 76, FALSE),
    (63, 'Super Mario Bros. 3', 'Platform', 1988, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ozx.jpg', 'Super Mario Bros. 3, the third entry in the Super Mario Bros. series and Super Mario franchise, sees Mario or Luigi navigate a nonlinear world map containing platforming levels and optional minigames and challenges. The game features more diverse movement options and new items alongside more complex level designs and boss battles.', 1068, FALSE),
    (64, 'Dark Souls', 'Role-playing (RPG)', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1x78.jpg', 'Dark Souls is an action role-playing game developed by FromSoftware and published by Bandai Namco Entertainment. Released in September 2011 as a spiritual sequel to Demon''s Souls, it is set in a dark, medieval fantasy world. It is renowned for its challenging gameplay, intricate level design, and deep lore. Players control a customizable character known as the Chosen Undead, embarking on a perilous journey to uncover the secrets of the cursed land of Lordran.

Dark Souls is known for its punishing difficulty, requiring players to carefully manage combat, stamina, and resources while navigating hostile environments filled with dangerous enemies and formidable bosses. The game features a unique multiplayer component, allowing players to leave messages for others, summon allies for cooperative play, or invade other players'' worlds for PvP combat.

The original release of Dark Souls received critical acclaim for its atmospheric world, innovative mechanics, and rewarding gameplay, solidifying its place as a seminal title in the action RPG genre.', 2155, FALSE),
    (65, 'The Legend of Zelda: A Link to the Past', 'Puzzle', 1991, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3vzn.jpg', 'Venture back to Hyrule and an age of magic and heroes. The predecessors of Link and Zelda face monsters on the march when a menacing magician takes over the kingdom. Only you can prevent his evil plot from shattering the land of Hyrule.

In your quest, you''ll venture into twisting mazes, dungeons, palaces and shadowy forests. Test your mettle with mighty swords and magical weapons. Or heft a boulder and hurl it at your enemies. If the going gets tough, dive into a river - you can swim to escape! Learn powerful spells, locate magical artifacts and solve the mysteries of the evil magician and the hidden realm of Hyrule.', 1026, FALSE),
    (66, 'Metal Gear Solid', 'Shooter', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobpak.jpg', 'Metal Gear Solid is a stealth game created by Hideo Kojima which follows the MSX2 video games Metal Gear and Metal Gear 2: Solid Snake. Despite a transition to 3D, Metal Gear Solid''s gameplay remains similar to his predecessors. The game utilizes a traditional top-down view and the player must navigate the protagonist Solid Snake through the game''s areas without being detected. Detection will set off an alarm which draws armed enemies to his location. Conversations with Snake''s allies and cutscenes are used extensively to advance the plot and gain more insight into it. Metal Gear Solid is regarded as one of the greatest and most important video games of all time, and helped popularize the stealth genre and in-engine cinematic cutscenes.', 375, FALSE),
    (67, 'The Last of Us Remastered', 'Shooter', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5zks.jpg', 'The Last of Us Remastered is an updated release of the PS3 game The Last of Us. It is identical to the PS3 version but runs at a 1080p resolution and incorporates character models with a higher resolution. There are also improved shadows and lighting, upgraded textures, 60 frames per second and other types of improvements. In addition to the base game, two map packs and the expansion The Last of Us: Left Behind are included.', 6036, FALSE),
    (68, 'Resident Evil 4', 'Shooter', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2wk8.jpg', 'Resident Evil 4 is the sixth installment in the Resident Evil series and is often noted for its departure from the fixed camera angles of earlier titles. It introduced an over-the-shoulder third-person perspective, faster-paced gunplay, and more dynamic controls. The game features larger, more open environments and a new AI system that enables enemies to coordinate attacks and attempt to corner the player. Enemies exhibit more human-like behavior, such as climbing ladders, opening doors, and using weapons.', 974, FALSE),
    (69, 'Inside', 'Platform', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fca.jpg', 'Inside is a puzzle-platformer developed by Playdead, presented in a 2.5D side-scrolling format with a dark, predominantly monochromatic visual style. The player controls an unnamed boy navigating a dystopian environment, solving environmental puzzles, avoiding hostile guards and creatures, and using a mind-control device to manipulate bodies in order to progress. The game features no dialogue or HUD, relying on visual and audio cues to guide the player through its increasingly surreal and dangerous settings.', 7342, FALSE),
    (70, 'Warcraft III: Reign of Chaos', 'Real Time Strategy (RTS)', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xuq.jpg', 'Warcraft III: Reign of Chaos is a real-time strategy game set in the high fantasy world of Azeroth. Players control one of four factions, the Human Alliance, Orcish Horde, Night Elves, or Undead Scourge, each with unique units, structures, and hero characters that gain experience and abilities through combat. The single-player campaign follows a sequential narrative across four faction-specific chapters. Multiplayer is supported through Battle.net with ranked matchmaking. The game includes a World Editor that allows players to create custom maps and scenarios, which gave rise to influential community creations including the mod Defense of the Ancients.', 132, FALSE),
    (71, 'Baldur''s Gate III', 'Role-playing (RPG)', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co670h.jpg', 'An ancient evil has returned to Baldur''s Gate, intent on devouring it from the inside out. The fate of Faerun lies in your hands. Alone, you may resist. But together, you can overcome.', 119171, FALSE),
    (72, 'Final Fantasy VII', 'Role-playing (RPG)', 1997, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kx2.jpg', 'The Western release of Final Fantasy VII (released as Final Fantasy VII International in Japan) included additional elements and alterations, such as streamlining of the menu and Materia system, reducing the health of enemies, new visual cues to help with navigation across the world map, and additional cutscenes relating to Cloud''s past.', 427, FALSE),
    (73, 'Limbo', 'Platform', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qrs.jpg', 'Limbo is a black and white puzzle-platforming adventure. Players take the role of a young boy traveling through an eerie and treacherous world in an attempt to discover the fate of his sister.', 1331, FALSE),
    (74, 'Grand Theft Auto III', 'Shooter', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lb8.jpg', 'Featuring a fully 3-D living city, a combination of narrative driven and non-linear gameplay and a completely open environment, Grand Theft Auto III represents a huge leap forward in interactive entertainment. For the first time, players are put at the heart of their very own gangster movie, and let loose in a fully-realised 3 dimensional city, in which anything can happen and probably will.

With a cast of hundreds, 50 plus vehicles, ranging from sports cars to ice cream trucks and from boats to buses, 3 hours of music, including opera, reggae, house, drum and bass, pop and disco, a huge array of street ready weapons and some of the seediest characters in video game history, Grand Theft Auto 3 is a sprawling epic which will show you that sometimes, crime can pay and sometimes it can pay you back. Available now for PlayStation2, Xbox, PC and Macintosh.', 730, FALSE),
    (75, 'Diablo II', 'Role-playing (RPG)', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gfq.jpg', 'Like its predecessor, Diablo II is an action role-playing game with dark fantasy and horror themes. The player controls a new hero attempting to stop the destruction unleashed by Diablo''s return. The game''s 4 acts feature a variety of locations and settings to explore and battle in, as well as an increased cast of characters to play as and interact with. Diablo II had become one of the most popular online games of all time. Major factors that contributed to Diablo II''s success include what fans found to be addictive hack-and-slash gameplay and free access to Battle.net.', 126, FALSE),
    (76, 'NieR: Automata', 'Role-playing (RPG)', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5pcj.jpg', 'NieR: Automata tells the story of androids 2B, 9S and A2 and their battle to reclaim the machine-driven dystopia overrun by powerful machines.', 11208, FALSE),
    (77, 'The Elder Scrolls IV: Oblivion', 'Role-playing (RPG)', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8fpz.jpg', 'The Elder Scrolls IV: Oblivion, the fourth game in the Elder Scrolls story, is set within the province of Cyrodiil, the heartland and Imperial capital of Tamriel. Emperor Uriel Septim VII is assassinated in flight from his own palace, but just before he dies he passes on to you the mystic Amulet of Kings. The adventure proper begins with the quest to find Uriel''s lost and illegitimate son who is the only heir to the throne. In a world where the forces of darkness seek their ultimate dominion over the ranks of man and mer alike, you alone stand between the future of Tamriel and the gates of Oblivion.', 59, FALSE),
    (78, 'Call of Duty: Modern Warfare 2', 'Shooter', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3cwt.jpg', 'Call of Duty: Modern Warfare 2 is a first-person shooter video game developed by Infinity Ward and published by Activision for the Xbox 360 and PlayStation 3 video game consoles and the Microsoft Windows operating system. Officially announced on February 11, 2009, the game was released worldwide on November 10, 2009. It is the sixth installment of the Call of Duty series and the direct sequel to Call of Duty 4: Modern Warfare, continuing the same storyline, with Call of Duty: Modern Warfare 3 set to end the storyline.', 559, FALSE),
    (79, 'Mafia', 'Fighting', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qrt.jpg', 'Mafia is a 3D action crime epic set in the seedy underworld of the 1930''s. Rise from the lowly but well-dressed Footsoldier, to an envied and feared Made Man in an era of mob hits, car chases, and bootlegging. Earn a reputation as a tough enforcer, daring getaway driver, and deadly hitman in your quest for respect and power within the Salieri Family.', 39, FALSE),
    (80, 'Ori and the Blind Forest', 'Platform', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y41.jpg', 'The forest of Nibel is dying. After a powerful storm sets a series of devastating events in motion, an unlikely hero must journey to find his courage and confront a dark nemesis to save his home. Ori and the Blind Forest tells the tale of a young orphan destined for heroics, through a visually stunning action-platformer crafted by Moon Studios for Xbox One and PC. Featuring hand-painted artwork, meticulously animated character performance, and a fully orchestrated score, Ori and the Blind Forest explores a deeply emotional story about love and sacrifice, and the hope that exists in us all.', 7344, FALSE),
    (81, 'Batman: Arkham Knight', 'Hack and slash/Beat ''em up', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coagib.jpg', 'Batman: Arkham Knight is an action-adventure game developed by Rocksteady Studios, released in 2015. It is the final installment in the Arkham series. Players control Batman as he faces Scarecrow, who unites Gotham''s criminals to destroy the Dark Knight. The mysterious Arkham Knight, a new adversary, aids Scarecrow in his plan.

The game features open-world exploration, stealth, combat, and puzzle-solving. A key addition is the Batmobile, used for traversal and combat. The story explores Batman’s psychological struggles and the collapse of his alliances as Gotham spirals into chaos.', 5503, FALSE),
    (82, 'Assassin''s Creed III', 'Adventure', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xii.jpg', 'Assassin''s Creed III is an open-world action-adventure game set primarily in 18th-century Colonial America during the American Revolution. Players control two characters across the story: Haytham Kenway, a British Templar operating during the French and Indian War, and his half-Mohawk son Ratonhnhaké:ton (also known as Connor), who becomes an Assassin. Gameplay takes place across Boston, New York City, and a large wilderness frontier, with free-running, stealth, and combat using weapons including tomahawks, muskets, bows, and the series'' signature Hidden Blades. The game introduces naval combat through Connor''s captaining of a warship, as well as hunting, a homestead economy system, and seasonal weather that affects gameplay. A modern-day framing narrative follows Desmond Miles using the Animus to relive his ancestors'' memories.', 1266, FALSE),
    (83, 'Star Wars: Knights of the Old Republic', 'Role-playing (RPG)', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tmz.jpg', 'Choose Your Path! Set 4,000 years before the Galactic Empire, you are the last hope for the Jedi Order and the Republic - can you master the ways of the Force to become their savior? Or will you fall to the dark side and achieve ultimate power? Hero, villain, peacekeeper, or chaos-bringer... you and your party will determine the fate of the galaxy!

Star Wars: Knights of the Old Republic is a role-playing video game. Players will be able to create their own characters and be able to choose what gender, appearance, class, skills, attributes, and feats they have throughout the game - no two characters will be the same!', 116, FALSE),
    (84, 'Celeste', 'Platform', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob9dh.jpg', 'Help Madeline survive her inner demons on her journey to the top of Celeste Mountain, in this super-tight platformer from the creators of TowerFall. Brave hundreds of hand-crafted challenges, uncover devious secrets, and piece together the mystery of the mountain.', 26226, FALSE),
    (85, 'Uncharted 3: Drake''s Deception', 'Shooter', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tp8.jpg', 'A search for the fabled "Atlantis of the Sands" propels fortune hunter Nathan Drake on a trek into the heart of the Arabian Desert. When the terrible secrets of this lost city are unearthed, Drake''s quest descends into a desperate bid for survival that strains the limits of his endurance and forces him to confront his deepest fears.', 512, FALSE),
    (86, 'Half-Life 2: Episode Two', 'Shooter', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mw2.jpg', 'Half-Life 2: Episode Two is a first-person shooter set in the aftermath of the Citadel''s destruction. Players control Gordon Freeman as he and Alyx Vance travel through forests and underground tunnels toward a resistance base, facing Combine forces and new enemy types along the way. The game emphasizes vehicle-based combat sequences alongside the series'' physics-driven puzzles and gunplay.', 247, FALSE),
    (87, 'Resident Evil 2', 'Shooter', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ir3.jpg', 'Resident Evil 2 is a remake of 1998''s Resident Evil 2. The game was not developed with the intent of improving the original, but rather a reimagining of the original story with redesigned maps, characters and story elements. Gameplay mechanics are more similar to Resident Evil 7: Biohazard though with the use of an over-the-shoulder camera.', 19686, FALSE),
    (88, 'Sekiro: Shadows Die Twice', 'Adventure', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2a23.jpg', 'Sekiro: Shadows Die Twice is an action-adventure game set in a reimagined late 1500s Sengoku-era Japan.

Players control Wolf, a shinobi on a mission to rescue his kidnapped lord and seek revenge on his enemies. The game emphasizes precise sword combat, stealth, and mobility, replacing traditional RPG elements with a posture-based dueling system.', 76882, FALSE),
    (89, 'Middle-earth: Shadow of Mordor', 'Role-playing (RPG)', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20pd.jpg', 'Middle-earth: Shadow of Mordor is a open world third-person action role-playing video game developed by Monolith Productions and published by Warner Bros. Interactive Entertainment, which takes place in the world of J.R.R. Tolkien''s Legendarium.

The game takes place in the 60-year gap between the events of Tolkien''s The Hobbit and The Lord of The Rings. It is a story of revenge, slaughter, and mystery set entirely in Mordor, the Land of Shadows. At its center is Talion, an ordinary man who loses everything, including his mortal life.

The game is set in a fully open world, and features various role-playing game elements such as experience points and skills. There are various ways the player can complete their main objective. Aside from the main storyline, there are various side quests and random events the player can complete within Mordor.

The melee system is inspired by that of the Batman Arkham series. Getting into a good fighting rhythm, using both regular attacks and counter-attacks will improve the player''s combo multiplier.

A unique feature of Middle-earth: Shadow of Mordor is the Nemesis system. Every enemy in the game has their own name, rank, and memory. These enemies will continue to do their own jobs and tasks even when they''re off screen. If the player does not kill an enemy in an encounter, this enemy will remember the player and change their tactics and conversations based on the encounter.', 3025, FALSE),
    (90, 'The Witcher 2: Assassins of Kings', 'Role-playing (RPG)', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wy4.jpg', 'This third-person dark fantasy Western RPG and sequel to The Witcher (2007), featuring multiple endings and branching narrative paths, follows the travels of Geralt of Rivia, witcher, who, after being falsely accused of regicide, sets out to clear his name and find the real killer, in a time of political turmoil and the brink of war between the imperialistic Nilfgaardian Empire and the Four Kingdoms.', 478, FALSE),
    (91, 'Chrono Trigger', 'Role-playing (RPG)', 1995, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3plw.jpg', 'In this turn-based Japanese RPG, young Crono must travel through time through a misfunctioning teleporter to rescue his misfortunate companion and take part in an intricate web of past and present perils. The adventure that ensues soon unveils an evil force set to destroy the world, triggering Crono''s race against time to change the course of history and bring about a brighter future.', 1802, FALSE),
    (92, 'Rise of the Tomb Raider', 'Shooter', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rqa.jpg', 'Rise of the Tomb Raider is a third-person action-adventure game in which players control Lara Croft as she searches for the legendary city of Kitezh and a promise of immortality. Combat involves firearms, stealth, and melee weapons, while semi-open hub areas offer challenge tombs with puzzles, side missions, and resource scavenging for crafting. Players earn experience and unlock skills across three trees focused on combat, hunting, and survival. The game features an Expeditions mode that allows replaying levels with modifiers in place of traditional multiplayer.', 7323, FALSE),
    (93, 'Call of Duty: Black Ops', 'Shooter', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wkl.jpg', 'Call of Duty: Black Ops is the seventh main Call of Duty game and the sequel to Call of Duty: World at War. The game differs from most previous installments, which would involve a usual three-country campaign, while Call of Duty: Black Ops features two playable countries (Russia and the USA) but only has an American campaign. Several new features are also introduced, such as dive-to-prone and the available use of a flashlight on certain weapons. Furthermore, the campaign''s playable characters now speak while being controlled by the player.

Extra game included within:

+ Zork (Apple II)', 545, FALSE),
    (94, 'Counter-Strike: Global Offensive', 'Shooter', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc32n.jpg', 'Counter-Strike: Global Offensive is a team-based multiplayer first-person shooter developed by Valve and Hidden Path Entertainment. Two teams, Terrorists and Counter-Terrorists, compete in objective-based rounds across various game modes including bomb defusal, hostage rescue, and deathmatch. The game features an economy system where players purchase weapons and equipment at the start of each round based on performance in previous rounds. Competitive matchmaking, community servers, and a robust skin trading ecosystem support a large active player base.', 1372, FALSE),
    (95, 'Wolfenstein: The New Order', 'Shooter', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21c0.jpg', 'Wolfenstein: The New Order is an action-adventure shooter game played from a first-person perspective. It is the semi-sequel to 2009''s Wolfenstein, however utilizes very little from the game and drops any direct references to veil or supernatural.

To progress through the story, the player battle enemies throughout levels. The game utilizes a health system in which players'' health is divided into separate sections that regenerate; if an entire section is lost, the player must use a health pack to replenish the missing health. In combat, a cover system can be used as assistance against enemies. The player have the ability to lean around, over, and under cover, which can be used as a tactical advantage during shootouts and stealth levels. The game gives the player a wide variety of weapon options—they can be found on the ground, retrieved from dead enemies, or removed from their stationary position and carried around.', 2031, FALSE),
    (96, 'Shadow of the Colossus', 'Platform', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ozz.jpg', 'An open-world action/adventure game in which a young wanderer, along with a stolen magical sword and his steed companion, trespasses a cursed land, makes a deal with an ancient being to bring a sacrificial victim back to life, and sets off to fulfill his end of the bargain, which involves tracking down and infiltrating the abodes of sixteen colossi and sacrificing them to achieve his goal.', 2207, FALSE),
    (97, 'Super Mario Bros.', 'Platform', 1985, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6pib.jpg', 'A side scrolling 2D platformer and first entry in the Super Mario franchise, Super Mario Bros. follows Italian plumber Mario as he treks across many levels of platforming challenges featuring hostile enemies to rescue Princess Peach from the evil king Bowser.', 358, FALSE),
    (98, 'Detroit: Become Human', 'Adventure', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocot9.jpg', 'Detroit: Become Human is an interactive narrative adventure game developed by Quantic Dream and released in 2018. Set in a near-future Detroit where androids serve humans, the story follows three android protagonists—Kara, Connor, and Markus—who shape the city’s fate through their choices. Gameplay combines exploration, dialogue interactions, and quick-time events, with branching storylines and multiple endings. The narrative explores themes of artificial intelligence, freedom, and morality.', 14362, FALSE),
    (99, 'Super Mario Galaxy', 'Platform', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21ro.jpg', 'A 3D platformer and first Wii entry in the Super Mario franchise, Super Mario Galaxy sees Mario jump across planets and galaxies with varying items, enemies, geographies and gravity mechanics in order to reach his enemy Bowser, who has attacked the Mushroom Kingdom and hijacked Princess Peach''s castle with her inside.', 1077, FALSE),
    (100, 'Metal Gear Solid 3: Snake Eater', 'Shooter', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ei5.jpg', 'Metal Gear Solid 3: Snake Eater is the prequel to the entire Metal Gear series. Most of the series'' defining gameplay elements have been carried over and as before, Snake must use stealth and wits rather than brute force to infiltrate enemy zones and eliminate his major adversaries. Unlike the previous games, this installment takes place in a large outdoor jungle. Snake is able to use camouflage, climb trees, hide in tall grass or wear clothes that make him less noticeable.', 379, FALSE),
    (101, 'Hotline Miami', 'Shooter', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vqp.jpg', 'A top-down slasher/shooter with unlockable gameplay-altering masks and weapons, featuring a neon-flavoured electronic aesthetic, in which a hitman receives anonymous calls ordering him to travel to certain residences and crime dens and massacre those within, as he stumbles through unreal visions and inconsistencies without any answers to how, why or who.', 1384, FALSE),
    (102, 'Mafia II', 'Shooter', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2n13.jpg', 'Mafia II is a third-person action-adventure game set in the fictional American city of Empire Bay between 1945 and 1951. Players control Vito Scaletta through a story-driven campaign involving organized crime, navigating an open world on foot or by vehicle. Gameplay combines shooting, driving, and limited melee combat, with a wanted system that escalates law enforcement response based on criminal activity. The game features era-appropriate vehicles, licensed period music across multiple radio stations, and a cover-based combat system.', 40, FALSE),
    (103, 'StarCraft', 'Real Time Strategy (RTS)', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9n6m.jpg', 'StarCraft is a real-time strategy game set in a distant sector of the Milky Way galaxy in the 26th century. Players command one of three species across separate campaigns: the Terrans, resourceful human colonists cut off from Earth; the Zerg, an insectoid swarm that assimilates other species; and the Protoss, a technologically advanced race with powerful psionic abilities. Each species features distinct units, structures, and strategic options. The game includes a story-driven single-player campaign for each faction and competitive multiplayer via Battle.net.', 230, FALSE)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    genre = EXCLUDED.genre,
    year = EXCLUDED.year,
    image = EXCLUDED.image,
    description = EXCLUDED.description,
    igdb_id = EXCLUDED.igdb_id,
    is_deleted = EXCLUDED.is_deleted,
    updated_at = NOW();

-- Synchronize the identity sequence with the highest inserted game ID.
SELECT setval(
    pg_get_serial_sequence('public.games', 'id'),
    COALESCE((SELECT MAX(id) FROM public.games), 1),
    EXISTS (SELECT 1 FROM public.games)
);

COMMIT;
